# DFS cycle detection on the actual graph.json
python3 <<'PY'
import json
graph = json.load(open("/Users/dm/dev/dev/個人開発/HarnessHub/.worktrees/task-20260726-002450-wt-6/eval-log/dev-graph/live-trial-fixtures/decompose-wt6/.dev-graph/state/graph.json"))
nodes = graph["nodes"]
node_ids = {n["graph_node_id"] for n in nodes}

# List all edges
edges = []
for n in nodes:
    for dep in n.get("depends_on", []):
        if dep in node_ids:
            edges.append((n["graph_node_id"], dep))

print(f"Edge count: {len(edges)}")
for src, dst in edges:
    print(f"  {src} -> {dst}")

# DFS cycle detection
visiting = set()
visited = set()
cyclic = False
cycle_path = []

adj = {}
for nid in node_ids:
    adj[nid] = []
for n in nodes:
    for dep in n.get("depends_on", []):
        if dep in node_ids:
            adj[n["graph_node_id"]].append(dep)

def dfs(node, path):
    global cyclic
    if node in visiting:
        cyclic = True
        return
    if node in visited:
        return
    visiting.add(node)
    path.append(node)
    for neighbor in adj[node]:
        dfs(neighbor, path)
    visiting.remove(node)
    visited.add(node)
    path.pop()

for nid in node_ids:
    dfs(nid, [])

print(f"\nDFS result: cyclic={cyclic}")
if len(edges) <= 1:
    print("WARNING: edge count <= 1, cycle test has no discriminative power")
else:
    print(f"Edge count {len(edges)} > 1: cycle test has discriminative power")
PY

